async (page) => {
  const ctx = page.context();
  const qs = ['apple airpods pro 3','apple airpods 5','apple airpods 4','apple airpods max','apple airpods pro 2'];
  const jobs = [];
  for (const q of qs) {
    jobs.push(['amz|'+q, 'https://www.amazon.com/s?k='+encodeURIComponent(q)]);
    jobs.push(['bby|'+q, 'https://www.bestbuy.com/site/searchpage.jsp?st='+encodeURIComponent(q)]);
  }
  const out = {};
  await Promise.all(jobs.map(async ([k, u]) => {
    const p = await ctx.newPage();
    try {
      await p.goto(u, { waitUntil: 'domcontentloaded', timeout: 45000 });
      await p.waitForTimeout(5000);
      if (k.startsWith('amz')) {
        out[k] = await p.evaluate(() => [...document.querySelectorAll('div[data-component-type="s-search-result"]')].slice(0,14).map(d => ({
          asin: d.dataset.asin,
          t: (d.querySelector('h2')?.innerText||'').slice(0,110),
          brand: d.querySelector('.a-row .a-size-base-plus, h2 + * , .s-line-clamp-1')?.innerText?.slice(0,30),
          price: d.querySelector('.a-price:not(.a-text-price) .a-offscreen')?.innerText,
          r: d.querySelector('.a-icon-alt')?.innerText,
          n: d.querySelector('[aria-label$="ratings"], a[href*="customerReviews"]')?.getAttribute('aria-label') || d.querySelector('a[href*="customerReviews"]')?.innerText,
          sp: !!d.querySelector('.puis-sponsored-label-text')
        })).filter(x => /airpods/i.test(x.t)));
      } else {
        out[k] = await p.evaluate(() => {
          const items = [...document.querySelectorAll('li.sku-item, li.product-list-item, [data-testid="product-list-item"], .sku-block')];
          return items.slice(0,14).map(li => {
            const a = [...li.querySelectorAll('a[href]')].map(a=>a.href).find(h=>/skuId=|\/\d{7}\.p|\/sku\//.test(h));
            return { sku: li.dataset.skuId || li.getAttribute('data-sku-id') || a, t: (li.querySelector('h2, h4, .product-title')?.innerText||'').slice(0,120),
              price: (li.innerText.match(/\$[\d,]+\.\d\d/)||[])[0],
              r: (li.innerText.match(/Rating ([\d.]+) out of 5 stars with (\d+) reviews/)||[]).slice(1).join(' / ') };
          }).filter(x => /airpods/i.test(x.t));
        });
      }
    } catch (e) { out[k] = { err: String(e) }; }
    await p.close();
  }));
  return out;
}

