  const jobs = [];
  for (const q of qs) {
    jobs.push(['amz|'+q, 'https://www.amazon.com/s?k='+encodeURIComponent(q)]);
    jobs.push(['bby|'+q, 'https://www.bestbuy.com/site/searchpage.jsp?st='+encodeURIComponent(q)]);
  }
  const out = {};
  await Promise.all(jobs.map(async ([k, u]) => {
    const p = await ctx.newPage();
    try {
      await p.goto(u, { waitUntil: 'domcontentloaded', timeout: 45000 });
      await p.waitForTimeout(5000);
      if (k.startsWith('amz')) {
        out[k] = await p.evaluate(() => [...document.querySelectorAll('div[data-component-type="s-search-result"]')].slice(0,16).map(d => {
          const tx = d.innerText;
          return { asin: d.dataset.asin, t: tx.replace(/\s+/g,' ').slice(0,140),
            price: d.querySelector('.a-price:not(.a-text-price) .a-offscreen')?.textContent,
            r: d.querySelector('.a-icon-alt')?.textContent,
            n: (tx.match(/\(([\d.,]+K?)\)/)||[])[1],
            nl: [...d.querySelectorAll('[aria-label]')].map(e=>e.getAttribute('aria-label')).find(s=>/rating/i.test(s)) };
        }).filter(x => /^(Sponsored )?(Best Seller |Overall Pick |Amazon's Choice )?Apple AirPods/i.test(x.t)));
      } else {
        out[k] = await p.evaluate(() => {
          const items = [...document.querySelectorAll('li.product-list-item, li.sku-item')];
          return items.slice(0,12).map(li => {
            const hs = [...new Set([...li.querySelectorAll('a[href]')].map(a=>a.href).filter(h=>/sku/i.test(h)))];
            return { hs: hs.slice(0,3), t: (li.querySelector('h2, h4, .product-title')?.innerText||'').slice(0,120),
              price: (li.innerText.match(/\$[\d,]+\.\d\d/)||[])[0],
              r: (li.innerText.match(/Rating ([\d.]+) out of 5 stars with (\d+) reviews/)||[]).slice(1).join(' / ') };
          }).filter(x => /^Apple - AirPods/i.test(x.t));
        });
      }
    } catch (e) { out[k] = { err: String(e) }; }
    await p.close();
  }));
  return out;
})(page);
