await (async (page) => {
  const ctx = page.context();
  const out = {};
  await Promise.all([
    ...['apple airpods','apple airpods pro 2','apple airpods max usb-c'].map(q => (async () => {
      const p = await ctx.newPage();
      try {
        await p.goto('https://www.bestbuy.com/site/searchpage.jsp?st='+encodeURIComponent(q), { waitUntil:'domcontentloaded', timeout:45000 });
        await p.waitForTimeout(5000);
        out['bby|'+q] = await p.evaluate(() => [...document.querySelectorAll('li.product-list-item')].filter(li=>/^Apple - AirPods/.test(li.querySelector('h2')?.innerText||'')).map(li => {
          const h = li.innerHTML;
          return { id: li.dataset.productId, t: li.querySelector('h2').innerText.slice(0,80),
            txt: li.innerText.replace(/\s+/g,' ').slice(0,330),
            nums: [...new Set(h.match(/(?<![\d.])\d{7,8}(?![\d.])/g)||[])].slice(0,8),
            skuCtx: (h.match(/.{0,40}sku.{0,60}/gi)||[]).slice(0,4) };
        }));
      } catch(e) { out['bby|'+q] = {err:String(e)}; }
      await p.close();
    })()),
    (async () => {
      const p = await ctx.newPage();
      try {
        await p.goto('https://www.amazon.com/dp/B0DGHMNQ5Z', { waitUntil:'domcontentloaded', timeout:45000 });
        await p.waitForTimeout(2000);
        out.amzAOD = await p.evaluate(async () => {
          const r = await fetch('/gp/product/ajax/aodAjaxMain/?asin=B0DGHMNQ5Z&pc=dp&experienceId=aodAjaxMain');
          const d = new DOMParser().parseFromString(await r.text(), 'text/html');
          return [...d.querySelectorAll('#aod-pinned-offer, #aod-offer')].map(o => o.innerText.replace(/\s+/g,' ').slice(0,260));
        });
      } catch(e) { out.amzAOD = {err:String(e)}; }
      await p.close();
    })()
  ]);
  return out;
})(page);
```

