        await p.goto('https://www.bestbuy.com/site/searchpage.jsp?st='+encodeURIComponent(q), { waitUntil:'domcontentloaded', timeout:45000 });
        await p.waitForTimeout(3000);
        for (let i=0;i<8;i++){ await p.mouse.wheel(0,900); await p.waitForTimeout(500); }
        await p.waitForTimeout(2000);
        out['bby|'+q] = await p.evaluate(() => [...document.querySelectorAll('li.product-list-item')].map(li => {
          const h = li.innerHTML; const t = li.querySelector('h2')?.innerText || '';
          if (!/AirPods (Pro 2|Max|4)/.test(t)) return null;
          return { id: li.dataset.productId, t: t.slice(0,80), txt: li.innerText.replace(/\s+/g,' ').replace(t,'').slice(0,200),
            ctx: [...new Set(h.match(/(?<![\d.])\d{7,8}(?![\d.])/g)||[])].map(n => { const i=h.indexOf(n); return h.slice(Math.max(0,i-90), i+20).replace(/\s+/g,' '); }).slice(0,6) };
        }).filter(Boolean));
      } catch(e) { out['bby|'+q] = {err:String(e)}; }
      await p.close();
    })()),
    (async () => {
